<?php
declare(strict_types=1);
require_once __DIR__.'/../config/auth.php';
$adminId=require_roles(['Administrator']);
require_once __DIR__.'/../config/db.php';
$page=$_GET['page']??'dashboard';$allowed=['dashboard','sellers','properties','auctions','activity','audit','notifications','staff','reports','settings'];if(!in_array($page,$allowed,true))$page='dashboard';
$name=(string)($_SESSION['username']??'Administrator');$initials=strtoupper(substr(preg_replace('/[^a-z]/i','',$name)?:'AD',0,2));$notice='';$error='';$q=trim((string)($_GET['q']??''));
function ah($v):string{return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}
function money($v):string{return '₱'.number_format((float)$v,2);}
function rows(mysqli $conn,string $sql,array $args=[]):array{$s = hb_query($conn, $sql, $args);return hb_fetch_all($s);}
function one(mysqli $conn,string $sql,array $args=[]):array{$s = hb_query($conn, $sql, $args);return hb_fetch_one($s)?:[];}
function logAdmin(mysqli $conn,int $uid,string $action,string $type,int $id):void{$s = hb_query($conn, 'INSERT INTO activity_logs(user_id,action,entity_type,record_id,ip_address) VALUES(?,?,?,?,?)', [$uid,$action,$type,$id,$_SERVER['REMOTE_ADDR']??null]);}
function pill(string $v):string{$x=strtolower($v);$c=(str_contains($x,'approv')||str_contains($x,'paid')||str_contains($x,'verified')||$x==='active'||$x==='confirmed'||$x==='accepted')?'green':((str_contains($x,'pending')||str_contains($x,'upcoming'))?'amber':((str_contains($x,'reject')||str_contains($x,'cancel')||str_contains($x,'fail'))?'red':'blue'));return '<span class="pill '.$c.'">'.ah($v).'</span>';}
function ico(string $n,int $s=18):string{$p=['grid'=>'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>','users'=>'<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87M16 3a4 4 0 0 1 0 8"/>','home'=>'<path d="m3 11 9-8 9 8M5 10v11h14V10M9 21v-7h6v7"/>','gavel'=>'<path d="m14 13-7 7-3-3 7-7m4-6 5 5m-7-3 5 5m-6-8 9 9"/>','chart'=>'<path d="M3 3v18h18M7 16l4-5 4 3 5-7"/>','settings'=>'<circle cx="12" cy="12" r="3"/><path d="M19 15a2 2 0 0 0 1 2l-3 3a2 2 0 0 0-3-1h-4a2 2 0 0 0-3 1l-3-3a2 2 0 0 0 1-3V9a2 2 0 0 0-1-3l3-3a2 2 0 0 0 3 1h4a2 2 0 0 0 3-1l3 3a2 2 0 0 0-1 3z"/>','search'=>'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>','bell'=>'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>','file'=>'<path d="M14 2H6a2 2 0 0 0-2 2v16h16V8zM14 2v6h6M8 13h8M8 17h5"/>','check'=>'<path d="m5 12 4 4L19 6"/>','clock'=>'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>','menu'=>'<path d="M4 7h16M4 12h16M4 17h16"/>','arrow'=>'<path d="M5 12h14m-6-6 6 6-6 6"/>'];return '<svg width="'.$s.'" height="'.$s.'" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">'.($p[$n]??$p['file']).'</svg>';}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$act=$_POST['action']??'';$id=filter_var($_POST['id']??0,FILTER_VALIDATE_INT);try{
if($act==='approve_property'&&$id){$s = hb_query($conn, 'UPDATE properties SET is_approved=1 WHERE id=?', [$id]);logAdmin($conn,$adminId,'Approved property listing','property',$id);$notice='Property approved.';$page='properties';}
elseif($act==='verify_seller'&&$id){$s = hb_query($conn, "UPDATE users SET is_verified=1 WHERE id=? AND role='Client'", [$id]);logAdmin($conn,$adminId,'Verified seller account','user',$id);$notice='Seller verified.';$page='sellers';}
elseif($act==='auction_status'&&$id){$v=$_POST['status']??'';if(!in_array($v,['upcoming','active','ended','cancelled'],true))throw new RuntimeException('Invalid auction status.');$s = hb_query($conn, 'UPDATE auctions SET status=? WHERE id=?', [$v,$id]);logAdmin($conn,$adminId,'Changed auction status to '.$v,'auction',$id);$notice='Auction status updated.';$page='auctions';}
elseif($act==='inquiry_status'&&$id){$v=$_POST['status']??'';if(!in_array($v,['pending','responded','closed'],true))throw new RuntimeException('Invalid inquiry status.');$s = hb_query($conn, 'UPDATE inquiries SET status=? WHERE id=?', [$v,$id]);logAdmin($conn,$adminId,'Updated inquiry status','inquiry',$id);$notice='Inquiry updated.';$page='notifications';}
elseif($act==='reservation_status'&&$id){$v=$_POST['status']??'';if(!in_array($v,['Pending','Approved','Cancelled','Completed'],true))throw new RuntimeException('Invalid reservation status.');$s = hb_query($conn, 'UPDATE reservations SET status=? WHERE id=?', [$v,$id]);logAdmin($conn,$adminId,'Updated reservation status','reservation',$id);$notice='Reservation updated.';$page='notifications';}
elseif($act==='viewing_status'&&$id){$v=$_POST['status']??'';if(!in_array($v,['Pending','Confirmed','Completed','Cancelled'],true))throw new RuntimeException('Invalid viewing status.');$s = hb_query($conn, 'UPDATE viewing_bookings SET status=? WHERE id=?', [$v,$id]);logAdmin($conn,$adminId,'Updated viewing request','viewing_booking',$id);$notice='Viewing request updated.';$page='notifications';}
elseif($act==='create_staff'){$u=trim($_POST['username']??'');$e=trim($_POST['email']??'');$pw=$_POST['password']??'';if(!$u||!filter_var($e,FILTER_VALIDATE_EMAIL)||strlen($pw)<8)throw new RuntimeException('Enter username, valid email and password with at least 8 characters.');$s = hb_query($conn, "INSERT INTO users(username,email,password,role,is_verified) VALUES(?,?,?,'Staff',1)", [$u,$e,password_hash($pw,PASSWORD_DEFAULT)]);$new=(int)mysqli_insert_id($conn);logAdmin($conn,$adminId,'Created staff account','user',$new);$notice='Staff account created.';$page='staff';}
elseif($act==='change_role'&&$id){$v=$_POST['role']??'';if(!in_array($v,['Administrator','Staff','Buyer','Client'],true)||$id===$adminId)throw new RuntimeException('Invalid role or cannot change your own role.');$s = hb_query($conn, 'UPDATE users SET role=? WHERE id=?', [$v,$id]);logAdmin($conn,$adminId,'Changed account role to '.$v,'user',$id);$notice='Account role updated.';$page='staff';}
else throw new RuntimeException('Action not available.');
}catch(Throwable $e){$error=$e instanceof mysqli_sql_exception?'Database action failed. Check the account details and database constraints.':'Database operation failed';error_log('Admin dashboard: '.'Database operation failed');}}
$st=one($conn,"SELECT (SELECT COUNT(*) FROM users) users,(SELECT COUNT(*) FROM users WHERE role='Client') sellers,(SELECT COUNT(*) FROM users WHERE role='Buyer') buyers,(SELECT COUNT(*) FROM properties) properties,(SELECT COUNT(*) FROM properties WHERE is_approved=0) pending,(SELECT COUNT(*) FROM properties WHERE is_approved=1) approved,(SELECT COUNT(*) FROM auctions WHERE status='active') active,(SELECT COUNT(*) FROM auctions WHERE status='ended') ended,(SELECT COUNT(*) FROM bids) bids");
$paid=one($conn,"SELECT COALESCE(SUM(amount),0) total FROM checkout_payments WHERE status='paid'");$pendingS=(int)(one($conn,"SELECT COUNT(*) n FROM users WHERE role='Client' AND is_verified=0")['n']??0);$tasks=$pendingS+(int)$st['pending']+(int)(one($conn,"SELECT COUNT(*) n FROM reservations WHERE status='Pending'")['n']??0);
$titles=['dashboard'=>'Overview','sellers'=>'Seller accounts','properties'=>'Property approvals','auctions'=>'Auction management','activity'=>'Bidding activity','audit'=>'Audit log','notifications'=>'Notifications','staff'=>'Staff & roles','reports'=>'Reports','settings'=>'System settings'];$nav=[['dashboard','grid','Overview',''],['sellers','users','Seller accounts',$pendingS],['properties','home','Property approvals',(int)$st['pending']],['auctions','gavel','Auction management',(int)$st['active']],['activity','chart','Bidding activity',''],['notifications','bell','Notifications','']];
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=ah($titles[$page])?> | HomeBid Admin</title><link rel="stylesheet" href="styles.css?v=1"></head><body><aside class="sidebar" id="sidebar"><div class="brand"><span class="brand-mark"><?=ico('home',20)?></span><div><b>HomeBid</b><small>Administration</small></div></div><nav class="nav-area"><div class="nav-group"><div class="nav-caption">Workspace</div><?php foreach($nav as [$id,$ic,$label,$count]):?><a class="nav-link <?=$page===$id?'active':''?>" href="?page=<?=$id?>"><?=ico($ic)?><span><?=ah($label)?></span><?php if($count!==''):?><em><?=ah($count)?></em><?php endif;?></a><?php endforeach;?></div><div class="nav-group"><div class="nav-caption">System</div><?php foreach([['audit','file','Audit log'],['staff','users','Staff & roles'],['reports','chart','Reports'],['settings','settings','System settings']] as [$id,$ic,$label]):?><a class="nav-link <?=$page===$id?'active':''?>" href="?page=<?=$id?>"><?=ico($ic)?><span><?=ah($label)?></span></a><?php endforeach;?></div></nav><div class="side-bottom"><div class="admin-user"><span class="avatar"><?=ah($initials)?></span><span><strong><?=ah($name)?></strong><small>Super Administrator</small></span><form method="post" action="../logout.php"><input type="hidden" name="csrf_token" value="<?=ah(csrf_token())?>"><button title="Log out"><?=ico('arrow',16)?></button></form></div></div></aside><button class="mobile-overlay" id="overlay" onclick="toggleSidebar()"></button><div class="main"><header class="topbar"><button class="menu-toggle" onclick="toggleSidebar()"><?=ico('menu')?></button><form class="searchbox"><input type="hidden" name="page" value="<?=$page?>"><?=ico('search')?><input name="q" value="<?=ah($q)?>" placeholder="Search users, properties, auctions..."></form><div class="top-right"><a class="icon-btn" href="?page=notifications"><?=ico('bell')?><i class="dot"></i></a><div class="top-user"><b><?=ah($name)?></b><small>Administrator</small></div><span class="top-avatar"><?=ah($initials)?></span></div></header><main class="content"><?php if($notice):?><div class="flash ok"><?=ah($notice)?></div><?php endif;?><?php if($error):?><div class="flash err"><?=ah($error)?></div><?php endif;?>
<?php if($page==='dashboard'):?>
<div class="page-heading"><div><p class="eyebrow"><?=date('l, F j')?></p><h1>Good morning, <?=ah($name)?></h1><p>Here’s what needs your attention across HomeBid today.</p></div><a class="btn primary" href="?page=properties">Review pending items <?=ico('arrow',15)?></a></div>
<section class="grid stats"><?php foreach([['Total registered users',$st['users'],'users',''],['Total sellers',$st['sellers'],'users',''],['Total buyers / bidders',$st['buyers'],'users',''],['Properties submitted',$st['properties'],'home',''],['Pending approvals',$st['pending'],'clock','gold'],['Approved properties',$st['approved'],'check','green'],['Ongoing auctions',$st['active'],'gavel','green'],['Completed auctions',$st['ended'],'chart','blue']] as [$l,$v,$ic,$tone]):?><article class="stat"><div class="stat-top"><span class="stat-icon <?=$tone?>"><?=ico($ic)?></span><span class="trend"><?=ah($l==='Pending approvals'?'Needs review':($l==='Ongoing auctions'?'Live now':'Platform total'))?></span></div><small><?=ah($l)?></small><strong><?=number_format((int)$v)?></strong></article><?php endforeach;?></section>
<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Auction performance</h2><p>Platform auction activity</p></div><span class="pill green">Live database</span></div><div class="panel-body"><div class="metric-row"><div class="metric"><small>Total paid payments</small><b><?=money($paid['total'])?></b></div><div class="metric"><small>Total bids</small><b><?=number_format((int)$st['bids'])?></b></div></div><div class="bar-chart"><?php $chart=rows($conn,"SELECT DATE_FORMAT(created_at,'%b') label,COUNT(*) total FROM auctions WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 6 MONTH) GROUP BY YEAR(created_at),MONTH(created_at),DATE_FORMAT(created_at,'%b') ORDER BY MIN(created_at)");$max=max(1,...array_map(fn($x)=>(int)$x['total'],$chart));for($i=0;$i<7;$i++):$v=(int)($chart[$i]['total']??0);?><div class="bar" title="<?=$v?> auctions" style="height:<?=max(5,$v/$max*95)?>%"></div><?php endfor;?></div><div class="bar-labels"><?php for($i=0;$i<7;$i++):?><span><?=ah($chart[$i]['label']??'—')?></span><?php endfor;?></div></div></article><article class="panel"><div class="panel-head"><div><h2>Pending tasks</h2><p>Items requiring administrator action</p></div><?=pill($tasks.' open')?></div><div class="task-list"><?php foreach([['Seller verifications',$pendingS.' applications','users','sellers'],['Property approvals',$st['pending'].' awaiting review','home','properties'],['Auction monitoring',$st['active'].' currently active','gavel','auctions'],['Customer requests','Reservations, viewings and inquiries','bell','notifications']] as [$l,$sub,$ic,$to]):?><a class="task" href="?page=<?=$to?>"><span class="task-icon"><?=ico($ic)?></span><span><b><?=ah($l)?></b><small><?=ah($sub)?></small></span><?=ico('arrow',15)?></a><?php endforeach;?></div></article></section>
<section class="grid two-col"><article class="panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest administrator and staff actions</p></div><a class="btn" href="?page=audit">View audit log</a></div><div class="panel-body"><?php $logs=rows($conn,'SELECT l.*,u.username FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.created_at DESC LIMIT 5');if(!$logs):?><div class="empty">Activity will appear here as staff and administrators work.</div><?php endif;?><?php foreach($logs as $l):?><div class="activity-row"><span class="task-icon"><?=ico('file',15)?></span><div><b><?=ah($l['action'])?></b><p><?=ah(($l['username']??'System').' · '.$l['entity_type'].' #'.($l['record_id']??'—'))?></p></div><time><?=ah(date('M j, g:i a',strtotime($l['created_at'])))?></time></div><?php endforeach;?></div></article><article class="panel announcement"><div class="announcement-banner"><small>System overview</small><h3>HomeBid platform operations</h3><p>Manage sellers, approve listings, monitor auctions, review bids and keep account access secure from one administration workspace.</p></div><div class="announcement-foot"><span>Administrator workspace</span><a href="?page=settings">Manage settings</a></div></article></section>
<?php elseif($page==='sellers'):?>
<div class="page-heading"><div><p class="eyebrow">USER ADMINISTRATION</p><h1>Seller accounts</h1><p>Verify client accounts and review property activity.</p></div></div><article class="panel"><div class="table-tools"><b>Seller directory</b><form class="search-inline"><input type="hidden" name="page" value="sellers"><input name="q" value="<?=ah($q)?>" placeholder="Search seller name or email"></form></div><div class="table-wrap"><table><thead><tr><th>Seller</th><th>Email</th><th>Joined</th><th>Listings</th><th>Verification</th><th>Action</th></tr></thead><tbody><?php $list=rows($conn,"SELECT u.*,COUNT(p.id) listings FROM users u LEFT JOIN properties p ON p.user_id=u.id WHERE u.role='Client' AND (u.username LIKE ? OR u.email LIKE ?) GROUP BY u.id ORDER BY u.created_at DESC",['%'.$q.'%','%'.$q.'%']);if(!$list):?><tr><td colspan="6" class="empty">No Client seller accounts found.</td></tr><?php endif;?><?php foreach($list as $u):?><tr><td><div class="person"><span class="avatar"><?=ah(strtoupper(substr($u['username'],0,2)))?></span><span><b><?=ah($u['username'])?></b><small>#USR-<?=$u['id']?></small></span></div></td><td><?=ah($u['email'])?></td><td><?=ah(date('M j, Y',strtotime($u['created_at'])))?></td><td><?=$u['listings']?></td><td><?=pill($u['is_verified']?'Verified':'Pending verification')?></td><td><?php if(!$u['is_verified']):?><form class="action-form" method="post"><input type="hidden" name="csrf_token" value="<?=ah(csrf_token())?>"><input type="hidden" name="action" value="verify_seller"><input type="hidden" name="id" value="<?=$u['id']?>"><button>Verify seller</button></form><?php else:?>Verified<?php endif;?></td></tr><?php endforeach;?></tbody></table></div></article>
<?php elseif($page==='properties'):?>
<div class="page-heading"><div><p class="eyebrow">LISTING ADMINISTRATION</p><h1>Property approvals</h1><p>Review seller property submissions and approve listings.</p></div><?=pill((int)$st['pending'].' awaiting review')?></div><article class="panel"><div class="table-tools"><div class="tabs"><a class="<?=($_GET['filter']??'pending')==='pending'?'active':''?>" href="?page=properties&filter=pending">Pending</a><a class="<?=($_GET['filter']??'')==='approved'?'active':''?>" href="?page=properties&filter=approved">Approved</a><a class="<?=($_GET['filter']??'')==='all'?'active':''?>" href="?page=properties&filter=all">All listings</a></div><form class="search-inline"><input type="hidden" name="page" value="properties"><input type="hidden" name="filter" value="<?=ah($_GET['filter']??'pending')?>"><input name="q" value="<?=ah($q)?>" placeholder="Search properties or seller"></form></div><?php $filter=$_GET['filter']??'pending';$where=$filter==='approved'?'p.is_approved=1':($filter==='all'?'1=1':'p.is_approved=0');$list=rows($conn,"SELECT p.*,u.username seller FROM properties p LEFT JOIN users u ON u.id=p.user_id WHERE $where AND (p.title LIKE ? OR p.location LIKE ? OR u.username LIKE ?) ORDER BY p.created_at DESC",['%'.$q.'%','%'.$q.'%','%'.$q.'%']);if(!$list):?><div class="empty">No properties in this view.</div><?php endif;?><?php foreach($list as $p):?><div class="property-card"><img src="<?=ah(!empty($p['image_path'])?(str_starts_with($p['image_path'],'http')?$p['image_path']:'../'.ltrim($p['image_path'],'/')):'../assets/property-alabang.jpg')?>" alt="<?=ah($p['title'])?>"><div><h3><?=ah($p['title'])?> <?=pill($p['is_approved']?'Approved':'Pending review')?></h3><p><?=ico('home',12)?> <?=ah($p['location'])?> · <?=ah($p['seller']??'Unknown seller')?></p><div class="property-meta"><span>Starting price <b><?=money($p['price'])?></b></span><span>Lot <?=ah($p['lot_area'])?> sqm</span><span>Floor <?=ah($p['floor_area'])?> sqm</span><span><?=ah(date('M j, Y',strtotime($p['created_at'])))?></span></div></div><div><?php if(!$p['is_approved']):?><form method="post" onsubmit="return confirm('Approve this property?')"><input type="hidden" name="csrf_token" value="<?=ah(csrf_token())?>"><input type="hidden" name="action" value="approve_property"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn primary">Approve listing</button></form><?php else:?><?=pill('Approved')?><?php endif;?></div></div><?php endforeach;?></article>
<?php elseif($page==='auctions'):?>
<div class="page-heading"><div><p class="eyebrow">AUCTION OPERATIONS</p><h1>Auction management</h1><p>Monitor schedules, bids and auction status.</p></div></div><article class="panel"><div class="table-tools"><b>All auctions</b><form class="search-inline"><input type="hidden" name="page" value="auctions"><input name="q" value="<?=ah($q)?>" placeholder="Search property"></form></div><div class="table-wrap"><table><thead><tr><th>Property</th><th>Starting bid</th><th>Current bid</th><th>Highest bidder</th><th>Schedule</th><th>Status / action</th></tr></thead><tbody><?php $list=rows($conn,'SELECT a.*,p.title,p.location,u.username bidder FROM auctions a JOIN properties p ON p.id=a.property_id LEFT JOIN users u ON u.id=a.highest_bidder_id WHERE p.title LIKE ? OR p.location LIKE ? ORDER BY a.created_at DESC',['%'.$q.'%','%'.$q.'%']);if(!$list):?><tr><td colspan="6" class="empty">No auctions found.</td></tr><?php endif;?><?php foreach($list as $a):?><tr><td><b><?=ah($a['title'])?></b></td><td><?=money($a['starting_bid'])?></td><td><?=money($a['current_bid'])?></td><td><?=ah($a['bidder']??'No bids yet')?></td><td><?=ah(date('M j, Y',strtotime($a['start_time'])))?><small style="display:block;color:#8a94a4">to <?=ah(date('M j, Y',strtotime($a['end_time'])))?></small></td><td><form class="action-form" method="post"><input type="hidden" name="csrf_token" value="<?=ah(csrf_token())?>"><input type="hidden" name="action" value="auction_status"><input type="hidden" name="id" value="<?=$a['id']?>"><select name="status"><?php foreach(['upcoming','active','ended','cancelled'] as $v):?><option <?=$a['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></div></article>
<?php elseif($page==='activity'):?>
<div class="page-heading"><div><p class="eyebrow">PLATFORM MONITOR</p><h1>Bidding activity</h1><p>Review bid history across all properties.</p></div></div><article class="panel"><div class="table-tools"><b>Bid history</b><form class="search-inline"><input type="hidden" name="page" value="activity"><input name="q" value="<?=ah($q)?>" placeholder="Search bidder or property"></form></div><div class="table-wrap"><table><thead><tr><th>Bid ID</th><th>Property</th><th>Bidder</th><th>Amount</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php $list=rows($conn,'SELECT b.*,p.title,u.username bidder FROM bids b JOIN properties p ON p.id=b.property_id JOIN users u ON u.id=b.user_id WHERE p.title LIKE ? OR u.username LIKE ? ORDER BY b.created_at DESC LIMIT 200',['%'.$q.'%','%'.$q.'%']);if(!$list):?><tr><td colspan="6" class="empty">No bids found.</td></tr><?php endif;?><?php foreach($list as $b):?><tr><td>#BID-<?=$b['id']?></td><td><b><?=ah($b['title'])?></b></td><td><?=ah($b['bidder'])?></td><td><b><?=money($b['bid_amount'])?></b></td><td><?=pill($b['status'])?></td><td><?=ah(date('M j, Y g:i a',strtotime($b['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></article>
<?php elseif($page==='audit'):?>
<div class="page-heading"><div><p class="eyebrow">SECURITY & ACCOUNTABILITY</p><h1>Audit log</h1><p>Track actions performed by administrators and staff.</p></div></div><article class="panel"><div class="table-tools"><b>System activity history</b><form class="search-inline"><input type="hidden" name="page" value="audit"><input name="q" value="<?=ah($q)?>" placeholder="Search action or user"></form></div><div class="table-wrap"><table><thead><tr><th>Action</th><th>Performed by</th><th>Entity</th><th>IP address</th><th>Date & time</th></tr></thead><tbody><?php $list=rows($conn,'SELECT l.*,u.username FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id WHERE l.action LIKE ? OR u.username LIKE ? OR l.entity_type LIKE ? ORDER BY l.created_at DESC LIMIT 250',['%'.$q.'%','%'.$q.'%','%'.$q.'%']);if(!$list):?><tr><td colspan="5" class="empty">No audit records yet.</td></tr><?php endif;?><?php foreach($list as $l):?><tr><td><b><?=ah($l['action'])?></b></td><td><?=ah($l['username']??'System')?></td><td><?=ah($l['entity_type'])?> #<?=ah($l['record_id']??'—')?></td><td><?=ah($l['ip_address']??'—')?></td><td><?=ah(date('M j, Y g:i a',strtotime($l['created_at'])))?></td></tr><?php endforeach;?></tbody></table></div></article>
